pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket{value: 1 ether}(1000);

        address referrer = address(0x1);
        vm.prank(referrer);
        c.getFreeKilo();

        address user = address(0x2);
        vm.prank(user);
        c.getFreeKilo();

        vm.warp(block.timestamp + 1);

        vm.prank(user);
        c.collectDrugs(referrer);

        uint256 refClaimed = c.claimedDrugs(referrer);
        assertEq(refClaimed, 60);
    }
}
